package com.library.reader; import com.library.common.*; import lombok.RequiredArgsConstructor; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequiredArgsConstructor public class ReaderController{private final ReaderMapper mapper;
@GetMapping("/api/readers")public Result<PageResult<Map<String,Object>>>page(@RequestParam(defaultValue="1")long page,@RequestParam(defaultValue="10")long size,@RequestParam(defaultValue="")String keyword){return Result.ok(new PageResult<>(mapper.count(keyword),mapper.search(keyword,(page-1)*size,size)));}
@GetMapping("/api/readers/{id}")public Result<Reader>one(@PathVariable Long id){return Result.ok(mapper.selectById(id));}@PostMapping("/api/readers")public Result<Void>add(@RequestBody Reader r){r.setStatus(1);r.setCreditScore(100);r.setDeleted(0);mapper.insert(r);return Result.ok();}@PutMapping("/api/readers/{id}")public Result<Void>update(@PathVariable Long id,@RequestBody Reader r){r.setId(id);mapper.updateById(r);return Result.ok();}@DeleteMapping("/api/readers/{id}")public Result<Void>delete(@PathVariable Long id){mapper.deleteById(id);return Result.ok();}}
